test('hash guard and reversible exact native patch',()=>{assert.throws(()=>patchBotModeWorkspace(Buffer.from('changed')),/Unexpected/);let text=patched;for(const[a,b]of[...PATCHES].reverse())text=text.replace(b,a);assert.equal(text,baseline.toString().replace(/\n\/\/# sourceMappingURL=client\.js\.map\s*$/u,'\n'));});
test('implicit blank reuse refreshes native projection and preserves recorded custom preset',async()=>{const f=fixture({preset:'stale-hint',fresh:'original-custom'});assert.equal(await f.self.createInWorkspace(f.workspace,{}),'native-blank');assert.deepEqual(f.refreshes,['native-blank']);assert.equal(f.calls[0].sessionId,'native-blank');assert.equal(f.calls[0].agentPreset,'original-custom');});
