test('projection read or unrelated preset error never silently defaults',async()=>{const unavailable=fixture({error:{refresh:true}});await assert.rejects(unavailable.self.createInWorkspace(unavailable.workspace,{}));assert.equal(unavailable.calls.length,0);const denied=fixture({error:{preset:'permission/denied'}});await assert.rejects(denied.self.createInWorkspace(denied.workspace,{}));assert.equal(denied.calls.length,1);});
